      url: '/bookings',
      payload: { roomId, userId, title, startsAt: inHours(startHours), endsAt: inHours(endHours) },
    });
  }

  async function availability(query: Record<string, string | number>) {
    const search = new URLSearchParams(
      Object.entries(query).map(([key, value]) => [key, String(value)]),
    ).toString();
    return app.inject({ method: 'GET', url: `/bookings/availability?${search}` });
  }

  it('answers 404 when the room does not exist', async () => {
    const response = await availability({ roomId: 'missing', from: inHours(24), to: inHours(30) });
    expect(response.statusCode).toBe(404);
  });

  it('returns the whole window as free when there are no bookings', async () => {
    const response = await availability({ roomId, from: inHours(24), to: inHours(30) });
    expect(response.statusCode).toBe(200);
    expect(response.json().slots).toHaveLength(1);
    expect(new Date(response.json().slots[0].startsAt).getTime()).toBe(new Date(inHours(24)).getTime());
    expect(new Date(response.json().slots[0].endsAt).getTime()).toBe(new Date(inHours(30)).getTime());
  });

  it('splits the window around an active booking', async () => {
    await book(25, 26);
    const response = await availability({ roomId, from: inHours(24), to: inHours(30) });
    const slots = response.json().slots;
    expect(slots).toHaveLength(2);
    expect(new Date(slots[0].endsAt).getTime()).toBe(new Date(inHours(25)).getTime());
    expect(new Date(slots[1].startsAt).getTime()).toBe(new Date(inHours(26)).getTime());
  });

  it('returns no slots when the room is fully booked in the window', async () => {
    await book(24, 30, 'All day');
    const response = await availability({ roomId, from: inHours(24), to: inHours(30) });
    expect(response.json().slots).toHaveLength(0);
  });

  it('frees the slot back up once the booking is cancelled', async () => {
    const created = await book(25, 26);
    await app.inject({ method: 'POST', url: `/bookings/${created.json().id}/cancel` });
    const response = await availability({ roomId, from: inHours(24), to: inHours(30) });
    expect(response.json().slots).toHaveLength(1);
  });

  it('drops gaps shorter than the minimum bookable duration', async () => {
    const response = await availability({ roomId, from: inHours(24), to: inHours(24.4) });
    expect(response.json().slots).toHaveLength(0);
  });

  it('drops gaps shorter than a requested duration', async () => {
    await book(25, 26);
    const response = await availability({ roomId, from: inHours(24), to: inHours(30), duration: 120 });
    const slots = response.json().slots;
    expect(slots).toHaveLength(1);
    expect(new Date(slots[0].startsAt).getTime()).toBe(new Date(inHours(26)).getTime());
  });
});

